from decimal import Decimal


_ZERO = Decimal("0")
_EIGHT = Decimal("8")
_TEN = Decimal("10")


def _numeric(value) -> Decimal:
    if value is None or value == "":
        return _ZERO
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def sweep(accounts: list[dict], orders: list[dict]) -> tuple[list[dict], list]:
    new_accounts = [dict(account) for account in accounts]
    audits = []

    eligible = [
        (index, account)
        for index, account in enumerate(accounts)
        if account.get("DEL_FLG") != "Y"
        and account.get("ACCT_TYP") == "C"
    ]
    eligible.sort(key=lambda item: item[1].get("ACCT_ID", ""))

    for index, account in eligible:
        acct_id = account.get("ACCT_ID")
        exposure = _ZERO

        for order in orders:
            if (
                order.get("DEL_FLG") != "Y"
                and order.get("ACCT_ID") == acct_id
                and order.get("STAT_CD") == "I"
            ):
                exposure += _numeric(order.get("TOT_AMT"))

        credit_limit = _numeric(account.get("CRED_LIMIT"))
        updated = new_accounts[index]

        if exposure > credit_limit and account.get("CRED_HOLD") != "Y":
            updated["CRED_HOLD"] = "Y"
            audits.append(("CRED_HOLD_ON", acct_id))

        if (
            exposure <= credit_limit * _EIGHT / _TEN
            and updated.get("CRED_HOLD", account.get("CRED_HOLD")) == "Y"
        ):
            updated["CRED_HOLD"] = "N"
            audits.append(("CRED_HOLD_OFF", acct_id))

    return new_accounts, audits
